import json, random, subprocess, sys, string

random.seed(1234)
ALPHA = string.printable + "\u00e9\u00ff\u0000\u0009\u001f\u007f\u0080"

def rand_value():
    n = random.randint(0,6)
    return ''.join(random.choice(ALPHA) for _ in range(n))

NAMES = [':method',':scheme',':authority',':path',':status','host','content-length','te','cookie',
         'accept','x-list-a','x-list-','x-audit-z','connection','trailer','transfer-encoding','X-Bad',
         'range','vary','if-match','x-audit-','upgrade','keep-alive','http2-settings','proxy-connection',
         'accept-encoding','cache-control','if-none-match','pragma','']
METHODS = ['GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS','CONNECT','get','']
SCHEMES = ['http','https','HTTPS','ws','']
PATHS = ['/','/a%2Fb?x=1','*','//x','/a b','/a#b','http://x/','/a%2','/a%2f%41','/%zz','','/a\\b','/é']
AUTHS = ['demo.test','Demo.test:443','demo.test:0443','demo.test:8443','[2001:db8::1]','[2001:db8::1]:8080',
         '[::ffff:192.0.2.1]','192.0.2.1','01.2.3.4','1.2.3.4.5','demo.test.','-a.test','a-.test','_x.test',
         'demo.test:0','demo.test:65536','demo.test:65535','','a','[::1%25eth0]','[not-ip]','x'*300]
HOSTS = AUTHS

def rand_section(trailer=False):
    n = random.randint(0,4)
    pairs = []
    for _ in range(n):
        if trailer:
            name = random.choice(['x-audit-a','x-audit-b','x-audit-','x-other','X-Audit-a',':method'])
        else:
            name = random.choice(NAMES)
        pairs.append([name, rand_value()])
    return pairs

def rand_stream(sid):
    events = []
    n = random.randint(1,5)
    for _ in range(n):
        t = random.choice(['headers','headers','data','unknown','fin','reset'])
        if t=='headers':
            events.append({'sid':sid,'type':'headers','fields':rand_section(random.random()<0.3)})
        elif t=='data':
            events.append({'sid':sid,'type':'data','hex':''.join(random.choice('0123456789abcdef') for _ in range(random.randint(0,8)*2))})
        elif t=='unknown':
            events.append({'sid':sid,'type':'unknown','frame_type':random.randint(0,100),'hex':'aa'})
        else:
            events.append({'sid':sid,'type':t})
    return events

def rand_scenario():
    routes = {}
    labels = ['a','b','c']
    for _ in range(random.randint(0,6)):
        routes[random.choice(['https://demo.test','http://demo.test','https://x.test:8443','http://[2001:db8::1]:8080'])] = random.choice(labels)
    events = []
    for sid in random.sample(range(0,40), random.randint(0,8)):
        evs = rand_stream(sid)
        # ensure terminal last
        events.extend(evs)
    return {'routes':routes,'events':events}

bad = 0
for i in range(600):
    scn = rand_scenario()
    p = subprocess.run([sys.executable,'/workspace/submission/bridge.py'],
                       input=json.dumps(scn).encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        bad += 1
        print("CRASH", p.stderr.decode()[-800:])
        print(json.dumps(scn)[:800])
        if bad > 3: break
        continue
    try:
        res = json.loads(p.stdout)
    except Exception as e:
        bad += 1; print("BADJSON", e); continue
    # structural checks
    assert set(res) == {'streams','origins'}, res.keys()
    for s in res['streams']:
        assert set(s) == {'sid','status','commit_at','origin','offset','length','cache_key'}
        assert s['status'] in ('forwarded','rejected','cancelled','incomplete')
        if s['status'] != 'forwarded':
            assert s['commit_at'] is None and s['origin'] is None and s['offset'] is None and s['length']==0 and s['cache_key'] is None
    for label in set(scn['routes'].values()):
        assert label in res['origins']
print("fuzz done, crashes:", bad)
